INSERT INTO kb.releases (id, label, changelog) VALUES (1, 'KB-PROD-0.1-LOT1', 'Lot 1 (brouillon IA) : dictionnaire transversal, Mg, mélatonine, vitamines C/B6/B9/B12, 6 plantes en liste de travail on-hold.') ON CONFLICT (id) DO NOTHING;
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('b589bb70-29bc-5c19-a731-cf484a985247', 'NE_PAS_DEPASSER', 'Ne pas dépasser la dose journalière recommandée', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Décret n° 2006-352 du 20 mars 2006, art. 10', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('92d48b66-826d-5a7f-8355-e3779c6dc0c5', 'HORS_PORTEE_ENFANTS', 'Tenir hors de portée des jeunes enfants', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Décret n° 2006-352 du 20 mars 2006, art. 10', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('2d6510fc-3a5f-576c-abe2-15349550259f', 'SUBSTITUT_REGIME', 'Les compléments alimentaires ne doivent pas être utilisés comme substituts d''un régime alimentaire varié et équilibré et d''un mode de vie sain', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Décret n° 2006-352 du 20 mars 2006, art. 10', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('7b9d4fa2-8d96-50b9-abfd-19a2a5e9b4de', 'MELATONINE_COUCHER', 'L''effet bénéfique est obtenu par la consommation de 1 mg de mélatonine peu de temps avant le coucher', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Règl. (UE) 432/2012, annexe : condition de l''allégation mélatonine / endormissement', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('ef0520f6-c996-5886-b816-55d34e02aaa8', 'MELATONINE_DECALAGE', 'L''effet bénéfique est obtenu par la consommation d''au moins 0,5 mg de mélatonine peu de temps avant le coucher le premier jour du voyage et les quelques jours suivant l''arrivée à destination', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Règl. (UE) 432/2012, annexe : condition de l''allégation mélatonine / décalage horaire', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('e58071b6-c232-5760-8b34-d86a3ab56b89', 'VITC_EXERCICE', 'L''effet bénéfique est obtenu par une consommation quotidienne de 200 mg de vitamine C en plus de l''apport journalier recommandé', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Règl. (UE) 432/2012, annexe : condition de l''allégation vitamine C / système immunitaire et exercice intense', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('dec19318-de2d-53d0-8a1c-64e2d218349a', 'FOLATES_ART14_POPULATION', 'Ce produit s''adresse aux femmes en âge de procréer', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Règlement d''autorisation art. 14 (acide folique / tube neural) : population cible', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('bcfd1218-4b22-5c10-8bb4-ce402d2c470a', 'FOLATES_ART14_EFFET', 'L''effet bénéfique est obtenu par une consommation quotidienne de 400 µg d''acide folique en complément, pendant au moins un mois avant et jusqu''à trois mois après la conception', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Règlement d''autorisation art. 14 (acide folique / tube neural) : conditions', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('a3823f5f-2e32-5240-9a23-e3d1178976c0', 'VIG_MELATONINE', 'Déconseillé aux femmes enceintes ou allaitantes, aux enfants et aux adolescents, ainsi qu''aux personnes souffrant de maladies inflammatoires ou auto-immunes. Demander l''avis d''un médecin en cas de traitement médicamenteux ou de pathologie. Prudence en cas d''activité nécessitant une vigilance soutenue', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Avis ANSES (2018) relatif aux compléments alimentaires contenant de la mélatonine — référence exacte à vérifier', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('b366002c-da92-5e59-b338-6afd4d3b960c', 'VIG_ASHWAGANDHA', 'Déconseillé aux femmes enceintes ou allaitantes, aux enfants et aux adolescents. Demander l''avis d''un médecin en cas de pathologie thyroïdienne, hépatique ou auto-immune, ou de traitement médicamenteux', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Signalements de nutrivigilance et avis d''autorités européennes — sources exactes à vérifier', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('4e963587-e8e9-5327-a371-9dc1b3759229', 'VIG_ADAPTOGENE_DONNEES', 'Déconseillé aux femmes enceintes ou allaitantes et aux enfants, faute de données suffisantes', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Prudence par défaut faute de données de sécurité — à confirmer par l''expert', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('19c87843-77a9-50fc-b3c5-91c8275bf23d', 'VIG_SEDATIF_VEGETAL', 'Déconseillé aux enfants de moins de 12 ans et aux femmes enceintes ou allaitantes. Peut entraîner une somnolence : prudence en cas de conduite. Demander l''avis d''un médecin en cas de traitement sédatif', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Monographies européennes (HMPC) valériane et passiflore — à vérifier', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('14048b31-9ffb-5f9d-a54e-6f102658b565', 'VIG_SAFRAN', 'Déconseillé aux femmes enceintes. Demander l''avis d''un médecin en cas de traitement antidépresseur', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Données de sécurité à forte dose et interactions — sources exactes à vérifier', 1);
INSERT INTO kb.mandatory_notices (id, code, text_fr, text_status, source_ref, introduced_in) VALUES ('7b01a54e-e274-537c-9238-405eadf4caf6', 'VIG_GINSENG', 'Déconseillé aux enfants et adolescents de moins de 18 ans et aux femmes enceintes ou allaitantes. Demander l''avis d''un médecin en cas d''hypertension, de diabète ou de traitement anticoagulant', 'FORMULATION_DE_TRAVAIL_VALIDEE', 'Monographie européenne (HMPC) ginseng et interactions rapportées — à vérifier', 1);
