INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('e1d5e1d5-b9ce-5996-bcc3-5290b226055a', 1, 'claim_conditions', 'MELATONINE-ENDORM-C2', 'MOYENNE', 'Vérifier la condition MENTION_OBLIGATOIRE {"placement": "RENVOI_ASTERISQUE"}.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('0c39800a-02c6-5822-bc2e-4689ec2880a4', 1, 'regulatory_claims', 'MELATONINE-JETLAG', 'MOYENNE', 'Libellé saisi avec une confiance MOYENNE : vérifier « La mélatonine contribue à atténuer les effets du décalage horaire » mot à mot.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('fff4f123-768f-5710-9fe8-6f4b1d5ef4af', 1, 'claim_conditions', 'MELATONINE-JETLAG-C1', 'MOYENNE', 'Vérifier la condition DOSE_MIN_PORTION {"amount": 0.5, "unit": "mg", "basis": "PORTION_QUANTIFIEE", "expressed_as": "SUBSTANCE"}.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('b7dcfcc3-3f9a-58e8-90f3-8f14fb016a12', 1, 'claim_conditions', 'MELATONINE-JETLAG-C2', 'MOYENNE', 'Vérifier la condition MENTION_OBLIGATOIRE {"placement": "RENVOI_ASTERISQUE"}.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('bb98003d-474a-5f49-b4c2-c2823be1eff8', 1, 'substances', 'MELATONINE', 'MOYENNE', 'Les allégations mélatonine ne visent que l''endormissement et le décalage horaire : « sommeil profond », « durée du sommeil » ou « qualité du sommeil » sont des allégations sans correspondance (motifs de risque).', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('25d24045-4856-5089-a807-4638b872ce5e', 1, 'substances', 'MELATONINE', 'MOYENNE', 'Vérifier la position française sur la dose journalière maximale de mélatonine en complément alimentaire (au-delà, risque de requalification en médicament).', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('d055def1-7e7f-5055-a5d9-b02d25aec421', 1, 'substances', 'MELATONINE', 'MOYENNE', 'Alias « mélatonine végétale » : même substance, même régime 432/2012 (ce n''est pas une botanique on-hold).', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('8daae591-77a2-5bea-abe3-01745b46afe9', 1, 'regulatory_claims', 'VIT_C-IMMUN-EXERCICE', 'MOYENNE', 'Libellé saisi avec une confiance MOYENNE : vérifier « La vitamine C contribue à maintenir le fonctionnement normal du système immunitaire pendant et après un exercice physique intense » mot à mot.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('03571eaf-4504-5b91-b94c-ef94ee19cbbf', 1, 'claim_conditions', 'VIT_C-IMMUN-EXERCICE-C1', 'MOYENNE', 'Vérifier la condition DOSE_MIN_PORTION {"amount": 200, "unit": "mg", "basis": "PORTION_JOURNALIERE", "expressed_as": "SUBSTANCE"}.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('82ee6c2b-94cd-5331-96b2-30b43825cfa9', 1, 'claim_conditions', 'VIT_C-IMMUN-EXERCICE-C2', 'MOYENNE', 'Vérifier la condition MENTION_OBLIGATOIRE {"placement": "RENVOI_ASTERISQUE"}.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('dc3fcaab-5097-5431-938e-1c3c00a706e5', 1, 'substances', 'VIT_C', 'MOYENNE', 'Lot 2 : la vitamine C est l''ancre « collagène » des formules collagène/acide hyaluronique ; l''effet ne doit jamais être attribué au collagène lui-même.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('fd3c17ff-be2a-5ca6-8962-831e2412aa2c', 1, 'substances', 'VIT_B6', 'MOYENNE', 'Vitamine B6 à forte dose : neuropathies rapportées ; limite supérieure de sécurité et dose maximale française à saisir pour le contrôle des doses (lot ultérieur).', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('26167a6e-3cf0-5e75-8516-0d8b1b87d4f5', 1, 'regulatory_claims', 'VIT_B9-TISSUS-MATERNELS', 'MOYENNE', 'Libellé saisi avec une confiance MOYENNE : vérifier « Les folates contribuent à la croissance des tissus maternels durant la grossesse » mot à mot.', 'assistant-ia');
