INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('6e9eb1c3-ec2b-53b3-ac22-5e1d6979fa6e', 1, 'regulatory_claims', 'VIT_B9-ART14-TUBE-NEURAL', 'MOYENNE', 'Libellé saisi avec une confiance MOYENNE : vérifier « La supplémentation en acide folique augmente le taux de folates maternels. Un faible taux de folates maternels est un facteur de risque de malformation du tube neural chez le fœtus en développement » mot à mot.', 'assistant-ia');
