INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('180caaf9-56b5-5ae3-9ca9-066c5e057bc9', 1, 'substances', 'VIT_B9', 'MOYENNE', 'Libellé « formation normale du sang » : traduction FR exacte incertaine (« hématopoïèse » ?), à vérifier mot à mot.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('086d29ae-6a9d-5eb0-9819-31e9a049e7d2', 1, 'substances', 'VIT_B9', 'MOYENNE', 'Allégation art. 14 : réservée à l''acide folique (forme synthétique) — conditions.py n''évalue pas encore « form_required » ; l''allégation doit rester CONDITIONNELLE tant que la forme n''est pas confirmée.', 'assistant-ia');
