INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('bd84ce96-5e60-5a28-a618-eeb72cccfd99', 1, 'seo_semantic_bridges', 'BR-ENERGIE', 'MOYENNE', 'Arbitrer l''équivalence de sens du terme légal « métabolisme énergétique ».', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('69489610-ab39-5c09-8050-c3ebd1e38715', 1, 'seo_semantic_bridges', 'BR-STRESS', 'MOYENNE', 'Arbitrer l''équivalence de sens du terme légal « stress ».', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('0c0f71fc-a3dd-5828-9b8b-9ac0aba38d68', 1, 'seo_semantic_bridges', 'BR-STRESS', 'MOYENNE', 'Pont sans ancrage publié : reporter à la release qui importera les allégations botaniques correspondantes.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('407bf17d-d17d-548f-8026-a76f17fd4e69', 1, 'seo_semantic_bridges', 'BR-INFECTIONS-SYSTEME-IMMUNITAIRE', 'MOYENNE', 'Arbitrer l''équivalence de sens du terme légal « système immunitaire ».', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('ce5c6a3b-abd7-55c4-850b-ff004e08e5fa', 1, 'GLOBAL', 'LIBELLES-432', 'HAUTE', 'Comparer CHAQUE libellé OFFICIEL_JOUE au texte français consolidé du Règl. (UE) 432/2012 sur EUR-Lex (accents, articles, ponctuation compris). Le statut OFFICIEL_JOUE est une intention, pas une preuve.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('89e10efb-0f8c-5a36-b4ad-ab4bdfdaa092', 1, 'GLOBAL', 'BASE-SOURCE-DE', 'MOYENNE', 'Confirmer la base de calcul de la « source de » pour un complément alimentaire (portion journalière recommandée) et l''expression en élément pour les minéraux.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('0b813d95-aa66-52ef-95fe-452328d3c226', 1, 'GLOBAL', 'VERBES-SUBSTITUTION', 'MOYENNE', 'Arbitrer les substitutions de verbe : « participe à », « aide à » pour « contribue à ». Si une substitution est acceptée, le générateur ajoute une variante V04 par allégation.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('befab027-12ea-5622-9d84-93b43bfccf49', 1, 'GLOBAL', 'ONHOLD-IMPORT', 'HAUTE', 'Importer la liste officielle des allégations botaniques en attente (identifiants, libellé source, conditions d''utilisation) pour les 6 plantes du lot, puis produire les traductions de travail.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('f0e372a0-078d-542f-aa74-a3989258035b', 1, 'GLOBAL', 'VOLUMES-SEO', 'MOYENNE', 'Mesurer les volumes de recherche des termes des ponts (source et date), sinon laisser NULL.', 'assistant-ia');
INSERT INTO kb.review_items (id, release_id, target_table, target_code, confidence, task_fr, author) VALUES ('65e11470-81a2-5d39-8c08-bbc9e5880d34', 1, 'GLOBAL', 'DOCTRINE-LEXIQUE', 'MOYENNE', 'Valider la gravité des entrées doctrinales (détox, réparateur, anti-…, booster) et des vocabulaires pharmaceutiques.', 'assistant-ia');
